def old(items):
    for x in items:
        if x > 10:
            return True
    return False


def new(items):
    return any(x > 10 for x in items)


def broken(items):
    return all(x > 10 for x in items)


for data in ([], [5], [20], [5, 20]):
    print(old(data) == new(data), old(data) == broken(data))
